package gobuf_test

import (
	"strings"
	"testing"

	"github.com/simonjanss/rig/internal/gen/gobuf"
)

func TestEmitsFormattedSource(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Doc("Package store is generated.")
	b.L("type Lesson struct {")
	b.L("ID %s.UUID", b.Import("github.com/google/uuid"))
	b.L("CreatedAt %s.Time", b.Import("time"))
	b.L("}")

	out, err := b.Bytes()
	if err != nil {
		t.Fatalf("emit: %v", err)
	}
	got := string(out)

	for _, want := range []string{
		"// Code generated by rig. DO NOT EDIT.",
		"// Package store is generated.",
		"package store",
		`"time"`,
		`"github.com/google/uuid"`,
		"\tID        uuid.UUID", // gofmt aligned the fields
	} {
		if !strings.Contains(got, want) {
			t.Errorf("missing %q:\n%s", want, got)
		}
	}
}

func TestStdlibImportsComeFirst(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Import("github.com/google/uuid")
	b.Import("time")
	b.Import("context")
	b.L("var _ = 1")

	out, _ := b.Bytes()
	got := string(out)

	stdEnd := strings.Index(got, `"time"`)
	thirdStart := strings.Index(got, `"github.com/google/uuid"`)
	if stdEnd < 0 || thirdStart < 0 || stdEnd > thirdStart {
		t.Errorf("standard library should come first:\n%s", got)
	}
}

func TestCollidingImportsAreAliased(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	first := b.Import("github.com/simonjanss/rig/runtime/query")
	second := b.Import("example.com/other/query")

	if first == second {
		t.Fatalf("both imports resolved to %q; one must be aliased", first)
	}

	b.L("var _ = %s.Op(\"\")", first)
	b.L("var _ = %s.Thing{}", second)
	out, err := b.Bytes()
	if err != nil {
		t.Fatalf("emit: %v", err)
	}
	if !strings.Contains(string(out), second+" ") {
		t.Errorf("the alias should appear in the import block:\n%s", out)
	}
}

func TestRepeatedImportReturnsTheSameName(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	if a, c := b.Import("time"), b.Import("time"); a != c {
		t.Errorf("Import is not stable: %q then %q", a, c)
	}
}

func TestCommentWraps(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.Comment(strings.Repeat("word ", 40) + "\n\nA second paragraph.")
	b.L("var _ = 1")

	out, _ := b.Bytes()
	for _, line := range strings.Split(string(out), "\n") {
		if len(line) > 80 {
			t.Errorf("line is %d characters:\n%s", len(line), line)
		}
	}
	if !strings.Contains(string(out), "//\n") {
		t.Error("the paragraph break was lost")
	}
}

// A syntax error in emitted code otherwise surfaces as an opaque gofmt
// complaint about a file nobody can see.
func TestBrokenSourceReportsItself(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.L("type Lesson struct {")
	// no closing brace

	_, err := b.Bytes()
	if err == nil {
		t.Fatal("unparseable source should be an error")
	}
	if !strings.Contains(err.Error(), "type Lesson struct {") {
		t.Errorf("the error should show the source:\n%v", err)
	}
	if !strings.Contains(err.Error(), "|") {
		t.Errorf("the source should be line-numbered:\n%v", err)
	}
}

// A module's major version is part of its path but not its package name.
// Taking the last segment would emit code referring to a package called v5.
func TestAVersionedPathIsImportedUnderItsRealName(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	for path, want := range map[string]string{
		"github.com/jackc/pgx/v5": "pgx",
		"github.com/google/uuid":  "uuid",
		"time":                    "time",
		// Only a v followed by digits is a version. A package genuinely called
		// "video" is not one.
		"example.com/x/video": "video",
		"example.com/x/v":     "v",
	} {
		if got := b.Import(path); got != want {
			t.Errorf("Import(%q) = %q, want %q", path, got, want)
		}
	}
}

// A file written once and then owned by a developer must not carry the banner:
// editing it is the entire point, and tools that recognize the banner would
// skip a file that is ordinary source.
func TestAHandOwnedFileHasNoBanner(t *testing.T) {
	t.Parallel()

	b := gobuf.NewHandOwned("todo")
	b.Doc("Package todo holds the business logic for todos.")
	b.L("// Service is where the rules live.")
	b.L("type Service struct{}")

	out, err := b.Bytes()
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(out), "DO NOT EDIT") {
		t.Errorf("a hand-owned file should not be marked generated:\n%s", out)
	}
	if !strings.Contains(string(out), "// Package todo holds") {
		t.Errorf("the package comment is missing:\n%s", out)
	}
}

// P builds a line in pieces, which is how a signature with a variable number of
// parameters gets written without assembling a format string first.
func TestPAndNLBuildALineByHand(t *testing.T) {
	t.Parallel()

	b := gobuf.New("store")
	b.P("func Get(")
	for i, arg := range []string{"ctx context.Context", "id uuid.UUID"} {
		if i > 0 {
			b.P(", ")
		}
		b.P("%s", arg)
	}
	b.L(") error { return nil }")
	b.NL()
	b.L("var _ = %s", gobuf.Quote(`a "quoted" string`))

	out, err := b.Bytes()
	if err != nil {
		t.Fatalf("%v", err)
	}
	body := string(out)
	if !strings.Contains(body, "func Get(ctx context.Context, id uuid.UUID) error") {
		t.Errorf("the pieces did not join:\n%s", body)
	}
	if !strings.Contains(body, `"a \"quoted\" string"`) {
		t.Errorf("Quote should produce a Go literal:\n%s", body)
	}
}

// Prose is reflowed and an example is not: the width prose was typed at is
// nobody's business, and reflowing an example changes what it says.
func TestCommentKeepsACodeBlock(t *testing.T) {
	t.Parallel()

	b := gobuf.New("demo")
	b.Comment("MinRevision refuses a caller older than this one.\n\n" +
		"\tMinRevision: apirev.MustParse(\"2026-04-30\"),\n\n" +
		"The zero value refuses nobody.")
	b.L("type S struct{ MinRevision int }")

	src, err := b.Bytes()
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(src), "//\tMinRevision: apirev.MustParse(\"2026-04-30\"),") {
		t.Errorf("the example was reflowed into the prose:\n%s", src)
	}
}
